import{G as e,W as t,n,rt as r}from"./chunks/framework.CMPLvzN_.js";var i=JSON.parse(`{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"常识/法律/法典.md","filePath":"常识/法律/法典.md"}`),a={name:`常识/法律/法典.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h2 id="中华人民共和国公司法" tabindex="-1">中华人民共和国公司法 <a class="header-anchor" href="#中华人民共和国公司法" aria-label="Permalink to “中华人民共和国公司法”">​</a></h2><p>必须通过<strong>国家企业信用信息公示系统公示</strong>公示的是：<strong>其公司股东实缴出资额和出资方式</strong></p><p>其他比如某公司与其他公司的合并决议、某公司股东会作出的减少注册资本的决议、某公司的破产清算公告都可以在报纸上进行公告。</p><h2 id="个人信息保护法" tabindex="-1">个人信息保护法 <a class="header-anchor" href="#个人信息保护法" aria-label="Permalink to “个人信息保护法”">​</a></h2><p>敏感个人信息是一旦泄露或者非法使用，容易导致自然人的<strong>人格尊严受到侵害</strong>或者<strong>人身、财产安全受到危害</strong>的个人信息。包括生物识别、宗教信仰、特定身份、医疗健康、金融账户、行踪轨迹等信息</p><h2 id="宪法" tabindex="-1">宪法 <a class="header-anchor" href="#宪法" aria-label="Permalink to “宪法”">​</a></h2><p>十三届全国人大将<strong>习近平新时代中国特色社会主义思想</strong>写入宪法</p><p><strong>宪法性法律</strong>一般是指有宪法规范存在其中，但形式上又不具备最高法律效力以及严格制定和修改程序的法律文件。</p><p>监督宪法实施的机构是<strong>全国人民代表大会及其常务委员会</strong></p><h2 id="乡村振兴促进法" tabindex="-1">乡村振兴促进法 <a class="header-anchor" href="#乡村振兴促进法" aria-label="Permalink to “乡村振兴促进法”">​</a></h2><p>坚持农业农村优先发展</p><p>构建以高质量绿色发展为导向的新型农业补贴政策体系</p><p>确保耕地总量不减少（土地红线，不需要增加，保证不减少就可以）</p>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};